H.background();
const alpha = P.alpha * 1e-6; // per K, slider in units of 1e-6
const L0 = P.L0; // m
const dT = P.dT; // K
const dL = alpha * L0 * dT;
const Lnew = L0 + dL;
H.text("Thermal expansion: dL = alpha * L0 * dT", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Heating lengthens a rod in proportion to its length and to dT", 24, 52, { color: H.colors.sub, size: 13 });
// animate dT sweeping toward set value for motion, but readout uses slider value
const sweep = 0.5 + 0.5*Math.sin(t*0.8); // 0..1
const dLanim = dL * sweep;
const x0 = 100, y = 300, pxPerM = 300;
const baseLen = L0 * pxPerM;
// exaggerate expansion visually so it's visible
const exag = 4000;
const drawLen = baseLen + dLanim*exag;
// rod
const hot = sweep; // color toward warm
H.rect(x0, y-18, Math.min(700, drawLen), 36, { fill: "rgba(220," + Math.round(120-80*hot) + ",60,0.85)", stroke: H.colors.ink, width: 2 });
// original length marker
H.line(x0+baseLen, y-40, x0+baseLen, y+40, { color: H.colors.sub, width: 1, dash:[4,4] });
H.text("L0", x0+baseLen-10, y-48, { color: H.colors.sub, size: 12 });
// current end
H.line(x0+Math.min(700,drawLen), y-50, x0+Math.min(700,drawLen), y+50, { color: H.colors.warn, width: 2 });
H.arrow(x0+baseLen, y-60, x0+Math.min(700,drawLen), y-60, { color: H.colors.warn, width: 3 });
H.text("dL (x" + exag + " shown)", x0+baseLen, y-66, { color: H.colors.warn, size: 11 });
// thermometer
const tx = 760;
H.rect(tx, 120, 24, 240, { stroke: H.colors.sub, width: 2 });
const fill = 240*sweep;
H.rect(tx, 360-fill, 24, fill, { fill: "rgba(220,60,60,0.8)" });
H.text("alpha = " + P.alpha.toFixed(1) + "e-6 /K", 24, 80, { color: H.colors.sub, size: 13 });
H.text("L0 = " + L0.toFixed(2) + " m,  dT = " + dT.toFixed(0) + " K", 24, 98, { color: H.colors.sub, size: 13 });
H.text("dL = " + (dL*1000).toFixed(3) + " mm,  L = " + Lnew.toFixed(5) + " m", 24, 116, { color: H.colors.good, size: 13 });
